mapper.select:
SELECT id, ds_id, metric_name, definition, calculation_rule, related_tables, related_columns, space_name, knowledge_source, confidence, verified, evidence, status, version, hit_count, error_count, create_time, update_time FROM kb_metric WHERE ds_id = #{dsId} AND verified = 1 AND status = 'active'
AND (metric_name LIKE CONCAT('%', #{keyword}, '%') OR definition LIKE CONCAT('%', #{keyword}, '%') OR related_tables LIKE CONCAT('%', '"', #{keyword}, '"', '%'))
AND space_name = #{spaceName}
ORDER BY confidence DESC, create_time DESC LIMIT #{topK}
